 IDisposable preferences;SportsScoreAcceptance.Tally tally;int checks;void Awake(){preferences=SportsPrefs.IsolateValidation("TargetFinalRestAwards");SportsParticipantRegistry.ForgetCache();}string folder;int errors;readonly StringBuilder log=new StringBuilder();void Check(bool ok,string label){checks++;log.AppendLine((ok?"PASS ":"FAIL ")+label);if(!ok)errors++;File.WriteAllText(folder+"/progress.txt",log.ToString());}void Error(string message,string stack,LogType type){if(type==LogType.Error||type==LogType.Exception){errors++;log.AppendLine("ERROR "+message);File.WriteAllText(folder+"/progress.txt",log.ToString());}}
